insert into public.tool_registry(key,category_id,name_ar,name_en,description_ar,description_en,url,icon,status,is_visible,is_platform,placement,sort_order,publish_status,draft_payload,version_no,short_slug,audience,health_status,published_at,updated_at)
values('tasks','platform','مهامي الدراسية','Study Tasks','منظم محلي للواجبات والاختبارات والتسليمات مع تنبيهات ذكية.','A local planner for assignments, exams, and deadlines with smart reminders.','tasks.html','✅','active',true,true,'home_primary',50,'published','{}'::jsonb,1,'tasks','{"type":"all"}'::jsonb,'healthy',now(),now())
on conflict (key) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,description_ar=excluded.description_ar,description_en=excluded.description_en,url=excluded.url,icon=excluded.icon,status='active',is_visible=true,is_platform=true,placement=excluded.placement,sort_order=excluded.sort_order,publish_status='published',audience=excluded.audience,updated_at=now(),version_no=public.tool_registry.version_no+1;
